/**
 * Handles {@link CityOwnerLimitException}, raised when an owner is created in a city that
 * already contains the maximum number of owners. Returns a 409 Conflict status.
 *
 * @param e The {@link CityOwnerLimitException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
 */
@ExceptionHandler(CityOwnerLimitException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleCityOwnerLimitException(CityOwnerLimitException e, HttpServletRequest request) {
    logger.warn("City owner limit reached at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.CONFLICT;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link DailyOwnerLimitException}, raised when an owner is created on a day that already
 * has the maximum number of owners registered. Returns a 429 Too Many Requests status.
 *
 * @param e The {@link DailyOwnerLimitException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
 */
@ExceptionHandler(DailyOwnerLimitException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
    logger.warn("Daily owner limit reached at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link InvalidPostcodeException}, raised when an owner is supplied with a postcode
 * that is out of range for its city's region. Returns a 400 Bad Request status.
 *
 * @param e The {@link InvalidPostcodeException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
 */
@ExceptionHandler(InvalidPostcodeException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
    logger.warn("Invalid postcode at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.BAD_REQUEST;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link FutureRegistrationDateException}, raised when an owner is supplied with a
 * {@code registrationDate} later than the current server date. Returns a 400 Bad Request status.
 *
 * @param e The {@link FutureRegistrationDateException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
 */
@ExceptionHandler(FutureRegistrationDateException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
    logger.warn("Future registration date at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.BAD_REQUEST;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

